protected Set fieldIdsToHash()
{
    Set fieldIdsSet = next fieldIdsToHash();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
        this.ModuleType == MarkupModuleType::Cust)
    {
        fieldIdsSet.add(fieldNum(MarkupAutoTable,Description));
    }

    return fieldIdsSet;
}

public void setPricingRuleReference(FieldId _pricingRuleFieldId, RefRecId _pricingRuleRecID)
{
    ttsbegin;

    this.selectForUpdate(true);
    this.(_pricingRuleFieldId) = _pricingRuleRecID;

    this.update();

    ttscommit;
}

public static MarkupAutoTable findMarkupAutoTableByRecId(RecId recId)
{
    MarkupAutoTable found;

    select firstonly found
        where found.recId == recId;

    return found;
}

public static void createOrUpdatePricingRuleForDataEntity(
    Common _entity,
    MarkupAutoTable _markupAutoTable,
    GUPPricingAttributeSourceLevel _sourceLevel,
    GUPGroupAll _type,
    GUPPricingAttributeGroupName _groupName)
{
    GUPPricingRule rule;
    str baseFieldName;

    if (_sourceLevel == GUPPricingAttributeSourceLevel::Header)
    {
        rule = GUPPricingRule::find(_markupAutoTable.PricingRuleHeader, true);
        baseFieldName = "Header";
    }
    else if (_sourceLevel == GUPPricingAttributeSourceLevel::Line)
    {
        rule = GUPPricingRule::find(_markupAutoTable.PricingRuleLine, true);
        baseFieldName = "Line";
    }

    switch (_type)
    {
        case GUPGroupAll::All :
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule("", GUPPricingRuleExclusionType::Customer);

                if (_sourceLevel == GUPPricingAttributeSourceLevel::Header)
                {
                    _markupAutoTable.PricingRuleHeader = rule.RecId;
                }
                else if (_sourceLevel == GUPPricingAttributeSourceLevel::Line)
                {
                    _markupAutoTable.PricingRuleLine = rule.RecId;
                }
            }

            if (rule.PriceAttributeGroupName)
            {
                rule.PriceAttributeGroupName = "";
                rule.update();
            }

            break;

        case GUPGroupAll::Group :

            ttsbegin;

            GUPPricingAttributeGroup attributeGroup = MarkupAutoTable::getAndValidateAttributeGroup(_groupName);
            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule(attributeGroup.Name, GUPPricingRuleExclusionType::Customer);

                if (_sourceLevel == GUPPricingAttributeSourceLevel::Header)
                {
                    _markupAutoTable.PricingRuleHeader = rule.RecId;
                }
                else if (_sourceLevel == GUPPricingAttributeSourceLevel::Line)
                {
                    _markupAutoTable.PricingRuleLine = rule.RecId;
                }

            }

            if (rule.PriceAttributeGroupName != attributeGroup.Name)
            {
                rule.PriceAttributeGroupName = attributeGroup.Name;
                rule.update();
            }

            int num = 1;

            GUPPricingAttributeLink attributeLink;

            while select attributeLink
                order by attributeLink.Priority asc
                where attributeLink.PriceAttributeGroupName == attributeGroup.Name
            {
                MarkupAutoTable::createOrUpdatePricingRuleCondition(rule.RecId, attributeLink.RecId, _entity.getFieldValue(baseFieldName + int2Str(num)), baseFieldName + int2Str(num));
                num ++;
            }

            ttscommit;
    }
}

private static boolean createOrUpdatePricingRuleCondition(RefRecId _ruleId, GUPRefRecId _conditionAttribute, AttributeValueText _value, str _fieldName)
{
    GUPPricingRuleCondition condition = GUPPricingRuleCondition::find(_ruleId, _conditionAttribute, true);

    if (condition)
    {
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.update();
    }
    else
    {
        condition.RuleId = _ruleId;
        condition.ConditionAttribute = _conditionAttribute;
        condition.ConditionValue = _value;
        if (!condition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, _fieldName));
        }
        condition.insert();
    }

    return true;
}

private static GUPPricingAttributeGroup getAndValidateAttributeGroup(Name _name)
{
    GUPPricingAttributeGroup attributeGroup;
    select firstonly attributeGroup
        where attributeGroup.Name == _name
           && attributeGroup.GroupType == GUPPricingAttributeGroupType::General;

    if (!attributeGroup)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPricingAttributeGroup), _name));
    }

    return attributeGroup;
}
